import { test, expect } from '@playwright/test';

test.describe('Locked-Out Customer Login Error Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display clear error message when locked-out user attempts to log in', async ({ page }) => {
    // Setup: intercept the login API with a locked-out response
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    // Intercept the locked-out response
    await page.route('**/api/auth/login', (route) => {
      route.continue({
        status: 403,
        body: JSON.stringify({
          success: false,
          message: 'User locked out',
          error: 'User has exceeded maximum login attempts'
        })
      });
    });

    // Attempt to log in with locked-out credentials
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('locked_out_user');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('secret_sauce');

    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Verify error message is displayed
    const errorContainer = page.getByTestId('error');
    await expect(errorContainer).toBeVisible();

    const errorMessage = page.getByText('Sorry, this user has been locked out');
    await expect(errorMessage).toBeVisible();

    // Verify error container has correct data-test attribute
    await expect(errorContainer).toHaveAttribute('data-test', 'error');

    // Verify user is not redirected to dashboard
    const dashboardLink = page.getByRole('link', { name: /dashboard/i });
    await expect(dashboardLink).not.toBeVisible();

    // Verify login form is still visible
    const loginForm = page.locator('[data-testid="login-form"]');
    await expect(loginForm).toBeVisible();
  });

  test('should not display error message when user is not locked out', async ({ page }) => {
    // Setup: intercept the login API with a success response
    await page.route('**/api/auth/login', (route) => {
      route.continue({
        status: 200,
        body: JSON.stringify({
          success: true,
          message: 'Login successful',
          user: {
            id: '123',
            username: 'unlocked_user'
          }
        })
      });
    });

    // Attempt to log in with valid credentials
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('unlocked_user');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('correct_password');

    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Verify user is redirected to dashboard
    const dashboardLink = page.getByRole('link', { name: /dashboard/i });
    await expect(dashboardLink).toBeVisible();

    // Verify error container is not displayed
    const errorContainer = page.getByTestId('error');
    await expect(errorContainer).not.toBeVisible();

    // Verify login form is not visible
    const loginForm = page.locator('[data-testid="login-form"]');
    await expect(loginForm).not.toBeVisible();
  });
});
